iv class="product-purchase"><strong>{data.product.price ? displayMoney(data.product.price.value) : 'Цена не указана'}{#if data.product.unit?.value}<span> / {data.product.unit.value}</span>{/if}</strong><button class="button" type="button" disabled={!available || cart.has(data.product.id) || !cart.ready} onclick={() => cart.add(data.product)}>{cart.has(data.product.id) ? 'В корзине' : available ? 'В корзину' : 'Недоступен для заказа'}</button></div>{#if cart.has(data.product.id)}<a class="read-link" href="/shop/cart">Перейти в корзину →</a>{/if}</div><div class="product-detail-image"><img src={data.product.image?.url || imageUrl(data.product.image?.hash, data.imageBase)} alt={data.product.image?.alt || data.product.value} width="600" height="600" onerror={imageFallback} /></div></div></section>
